#!/usr/bin/env node
/**
 * Emit assets/data/course-titles.json — a small bilingual lookup
 * from lesson slug → { module, position, path_en, path_es,
 * title_en, title_es }. Read by /account/ and /es/account/ to
 * render the course tile as "Lesson N — title — resume" instead
 * of the bare "N / 16".
 *
 * Source: data/course-lessons.json. Cap: ≤4 KB final size so it
 * inlines cheaply on the account dashboard.
 *
 *   node scripts/build-course-titles-bundle.mjs           # rewrite
 *   node scripts/build-course-titles-bundle.mjs --check   # exit 1 on diff
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const repoRoot   = path.resolve(path.dirname(__filename), '..');
const checkOnly  = process.argv.includes('--check');

const SRC = path.join(repoRoot, 'data', 'course-lessons.json');
const OUT = path.join(repoRoot, 'assets', 'data', 'course-titles.json');

const manifest = JSON.parse(fs.readFileSync(SRC, 'utf8'));

const bundle = {
  _doc: 'Auto-generated by scripts/build-course-titles-bundle.mjs. Source: data/course-lessons.json. Consumed by /account/ + /es/account/ to render course progress tile copy.',
  totalLessons: manifest.totalLessons,
  lessons: {}
};

for (const lesson of manifest.lessons) {
  bundle.lessons[lesson.id] = {
    module: lesson.module,
    position: lesson.position,
    path_en: lesson.path,
    path_es: '/es' + lesson.path,
    title_en: (lesson.title && lesson.title.en) || lesson.id,
    title_es: (lesson.title && lesson.title.es) || lesson.id
  };
}

const content = JSON.stringify(bundle, null, 2) + '\n';

fs.mkdirSync(path.dirname(OUT), { recursive: true });
const prev = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';

if (prev === content) {
  console.log('course-titles bundle: unchanged.');
  process.exit(0);
}

if (checkOnly) {
  console.error('course-titles bundle: drift detected. Run `node scripts/build-course-titles-bundle.mjs` to refresh.');
  process.exit(1);
}

fs.writeFileSync(OUT, content);
const sizeKb = (Buffer.byteLength(content) / 1024).toFixed(1);
console.log(`course-titles bundle: wrote ${path.relative(repoRoot, OUT)} (${sizeKb} KB, ${manifest.lessons.length} lessons).`);
